parameters.query:
query BuildingContext($buildingId: UUID!, $equipmentTake: Int!, $pointTake: Int!) {
  selected: buildings(take: 1, where: { id: { eq: $buildingId } }) {
    id
    equipment(take: $equipmentTake) {
      id
      points(take: $pointTake) { id value unit timestamp }
    }
  }
}
query BuildingIdentity($buildingId: UUID!) {
  buildings(take: 1, where: { id: { eq: $buildingId } }) { id name }
}
